/** Languages shipped by the game. Persist these stable BCP-47 tags in save data. */
export const GAME_LANGUAGES = [
  "zh-CN",
  "zh-TW",
  "en",
  "ja",
  "ko",
  "es",
  "pt",
  "fr",
  "de",
  "ru",
] as const;

export type GameLanguage = (typeof GAME_LANGUAGES)[number];

export interface GameLanguageMetadata {
  language: GameLanguage;
  nativeName: string;
  englishName: string;
}

/** Native names remain readable even before the player understands the active locale. */
export const GAME_LANGUAGE_METADATA: readonly GameLanguageMetadata[] = [
  { language: "zh-CN", nativeName: "简体中文", englishName: "Simplified Chinese" },
  { language: "zh-TW", nativeName: "繁體中文", englishName: "Traditional Chinese" },
  { language: "en", nativeName: "English", englishName: "English" },
  { language: "ja", nativeName: "日本語", englishName: "Japanese" },
  { language: "ko", nativeName: "한국어", englishName: "Korean" },
  { language: "es", nativeName: "Español", englishName: "Spanish" },
  { language: "pt", nativeName: "Português", englishName: "Portuguese" },
  { language: "fr", nativeName: "Français", englishName: "French" },
  { language: "de", nativeName: "Deutsch", englishName: "German" },
  { language: "ru", nativeName: "Русский", englishName: "Russian" },
] as const;

const GAME_LANGUAGE_SET = new Set<string>(GAME_LANGUAGES);

export const isGameLanguage = (value: unknown): value is GameLanguage => (
  typeof value === "string" && GAME_LANGUAGE_SET.has(value)
);

const resolveLanguageTag = (rawTag: unknown): GameLanguage | undefined => {
  if (typeof rawTag !== "string") return undefined;
  const tag = rawTag.trim().replace(/_/g, "-").toLowerCase();
  if (!tag) return undefined;

  const parts = tag.split("-").filter(Boolean);
  const base = parts[0];
  if (base === "zh") {
    // Script is authoritative when present; otherwise map the traditional
    // writing regions explicitly and use Simplified Chinese for bare zh.
    if (parts.includes("hant")) return "zh-TW";
    if (parts.includes("hans")) return "zh-CN";
    return parts.some((part) => part === "tw" || part === "hk" || part === "mo")
      ? "zh-TW"
      : "zh-CN";
  }

  if (base && GAME_LANGUAGE_SET.has(base)) return base as GameLanguage;
  return undefined;
};

/**
 * Selects the first supported locale from an ordered device preference list.
 * Browser (`en-US`) and WeChat (`zh_CN`) spellings are both accepted.
 */
export const resolvePreferredLanguage = (
  locales: readonly unknown[] | unknown,
): GameLanguage => {
  const candidates = Array.isArray(locales) ? locales : [locales];
  for (const candidate of candidates) {
    const resolved = resolveLanguageTag(candidate);
    if (resolved) return resolved;
  }
  return "en";
};

