const ENGLISH_TRANSLATIONS = {
  ...CORE_ENGLISH_TRANSLATIONS,
  ...PLAYER_UI_ENGLISH_TRANSLATIONS,
} as const;

export type TranslationKey = keyof typeof ENGLISH_TRANSLATIONS;
type PlayerUiTranslationKey = keyof typeof PLAYER_UI_ENGLISH_TRANSLATIONS;
type PlayerUiTranslationDictionary = Readonly<Record<PlayerUiTranslationKey, string>>;
type PlaceholderNames<Value extends string> = (
  Value extends `${string}{${infer Name}}${infer Rest}`
    ? Name | PlaceholderNames<Rest>
    : never
);

/** Parameter names are inferred from the English source string for each key. */
export type TranslationParams<Key extends TranslationKey> = (
  [PlaceholderNames<(typeof ENGLISH_TRANSLATIONS)[Key]>] extends [never]
    ? Readonly<Record<string, never>>
    : Readonly<Partial<Record<
      PlaceholderNames<(typeof ENGLISH_TRANSLATIONS)[Key]>,
      string | number
    >>>
);
type TranslationDictionary = Readonly<Record<TranslationKey, string>>;

