export const TRANSLATIONS: Readonly<Record<GameLanguage, TranslationDictionary>> = {
  "zh-CN": { ...ZH_CN_TRANSLATIONS, ...ZH_CN_PLAYER_UI },
  "zh-TW": { ...ZH_TW_TRANSLATIONS, ...ZH_TW_PLAYER_UI },
  en: ENGLISH_TRANSLATIONS,
  ja: { ...JA_TRANSLATIONS, ...JA_PLAYER_UI },
  ko: { ...KO_TRANSLATIONS, ...KO_PLAYER_UI },
  es: { ...ES_TRANSLATIONS, ...ES_PLAYER_UI },
  pt: { ...PT_TRANSLATIONS, ...PT_PLAYER_UI },
  fr: { ...FR_TRANSLATIONS, ...FR_PLAYER_UI },
  de: { ...DE_TRANSLATIONS, ...DE_PLAYER_UI },
  ru: { ...RU_TRANSLATIONS, ...RU_PLAYER_UI },
};

export const TRANSLATION_KEYS = Object.freeze(
  Object.keys(ENGLISH_TRANSLATIONS) as TranslationKey[],
);

/** Replaces named placeholders while leaving missing values visible for QA. */
export const translate = <Key extends TranslationKey>(
  language: GameLanguage,
  key: Key,
  params: TranslationParams<Key> = {} as TranslationParams<Key>,
): string => {
  const values = params as Readonly<Record<string, string | number | undefined>>;
  return TRANSLATIONS[language][key].replace(
    /\{([A-Za-z][A-Za-z0-9_]*)\}/g,
    (placeholder, name: string) => (
      Object.prototype.hasOwnProperty.call(values, name) ? String(values[name]) : placeholder
    ),
  );
};
